function check(value, message) { if (!value) throw new Error(message); }
const base = context.configuredValues.baseURL;
check(/^http:\/\/127\.0\.0\.1:[0-9]+$/.test(base), 'Use the neutral loopback server');
const original = editor.getText();
const http = HTTP.create();
http.timeout = 5;
const json = http.request({url:base+'/json',method:'GET'});
check(json instanceof HTTPResponse && json.success && json.statusCode===200,'HTTP success');
check(json.responseData.text==='café 🐼' && JSON.parse(json.responseText).text==='café 🐼','HTTP Unicode');
check(Object.keys(json.headers).some(k=>k.toLowerCase()==='x-neutral' && json.headers[k]==='yes'),'HTTP headers');
check(json.error===undefined && json.otherData===undefined,'Absent HTTP optional fields');
const latin = http.request({url:base+'/latin1',method:'GET'});
check(latin.success && latin.responseText==='café','HTTP charset');
const failure = http.request({url:base+'/error',method:'GET'});
check(!failure.success && failure.statusCode===503 && failure.responseText==='Unavailable café 🐼','HTTP non-success');
const disconnected = http.request({url:base+'/disconnect',method:'GET'});
check(!disconnected.success && disconnected.statusCode===0 && typeof disconnected.error==='string','HTTP transport error');
for (const path of ['/xml-latin1','/xml-utf16','/xml-utf16le-no-charset','/xml-utf16be-no-charset']) {
 const result = XMLRPC.request(base+path,'example.echo',[]);
 check(result instanceof XMLRPCResponse && result.success && result.statusCode===200,'XML-RPC success '+path);
 check(result.params.length===1 && result.params[0]==='café & mañana','XML-RPC encoding '+path);
 check(result.error===undefined && result.faultCode===undefined,'Absent XML-RPC error fields');
}
for (const code of [-42,0,42]) {
 const fault = XMLRPC.request(base+'/xml-fault?code='+code,'example.fault',[]);
 check(!fault.success && fault.statusCode===200 && fault.faultCode===code,'XML-RPC fault code');
 check(fault.error==='Denied café 🐼' && fault.params.length===0,'XML-RPC fault fields');
}
for (const [path,status] of [['/xml-malformed-array',200],['/xml-http-failure',503],['/bodyless',204],['/disconnect',0]]) {
 const result = XMLRPC.request(base+path,'example.invalid',[]);
 check(!result.success && result.statusCode===status,'XML-RPC failure status '+path);
 check(typeof result.error==='string' && result.error.length>0 && result.faultCode===undefined && result.params.length===0,'XML-RPC failure fields '+path);
}
check(editor.getText()===original,'Source text unchanged');
context.addSuccessParameter('loopback','HTTP and XML-RPC response checks passed');

function check(value,message){if(!value)throw new Error(message);}
const base=context.configuredValues.baseURL;
check(/^http:\/\/127\.0\.0\.1:[0-9]+$/.test(base),'Use the neutral loopback server');
const original=editor.getText();
const empty=XMLRPC.request(base+'/xml-echo','example.empty',[]);
check(empty instanceof XMLRPCResponse && empty.success && empty.statusCode===200,'Empty success');
check(Array.isArray(empty.params) && empty.params.length===0 && empty.error===undefined && empty.faultCode===undefined,'Empty fields');
const input=['café 🐼 <&',false,true,-42,1.25,{'key café 🐼':['  whitespace  ',[],{},null]}];
const result=XMLRPC.request(base+'/xml-echo','example.echo',input);
check(result.success && result.statusCode===200 && JSON.stringify(result.params)===JSON.stringify(input),'Nested round trip');
check(result.error===undefined && result.faultCode===undefined,'Nested fields');
result.params[5]['key café 🐼'][0]='changed';
check(input[5]['key café 🐼'][0]==='  whitespace  ' && empty.params.length===0,'Independent values');
check(editor.getText()===original,'Source text unchanged');
context.addSuccessParameter('xmlrpc','Empty and nested parameter round trips passed');
